import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // left[i]: non-increasing steps ending at i; right[i]: non-decreasing steps starting at i.
        int[] left = new int[n], right = new int[n];
        for (int i = 1; i < n; i++) left[i] = a[i - 1] >= a[i] ? left[i - 1] + 1 : 0;
        for (int i = n - 2; i >= 0; i--) right[i] = a[i] <= a[i + 1] ? right[i + 1] + 1 : 0;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (left[i] >= k && right[i] >= k) {
                if (out.length() > 0) out.append(' ');
                out.append(i + 1);
            }
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// left[i]: non-increasing steps ending at i; right[i]: non-decreasing steps starting at i.
	left, right := make([]int, n), make([]int, n)
	for i := 1; i < n; i++ {
		if a[i-1] >= a[i] {
			left[i] = left[i-1] + 1
		}
	}
	for i := n - 2; i >= 0; i-- {
		if a[i] <= a[i+1] {
			right[i] = right[i+1] + 1
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	first := true
	for i := 0; i < n; i++ {
		if left[i] >= k && right[i] >= k {
			if !first {
				w.WriteByte(' ')
			}
			first = false
			w.WriteString(strconv.Itoa(i + 1))
		}
	}
	w.WriteByte('\n')
}
